comp.model:
{
  "searchText": {{ stateSearchText.value }},
  "statusFilter": {{ stateStatusFilter.value }},
  "currentPage": {{ stateCurrentPage.value }},
  "modalStatus": {{ stateModalStatus.value }},
  "modalPage": {{ stateModalPage.value }},

  // dữ liệu từ query
  "logs": {{ logsPageQuery.data || [] }},
  "logsTotal": {{
    (logsCountQuery.data && logsCountQuery.data[0])
      ? logsCountQuery.data[0].total
      : 0
  }},
  "stats": {{
    (statsQuery.data && statsQuery.data[0])
      ? statsQuery.data[0]
      : {}
  }},
  "stations": {{ stationsQuery.data || [] }},
  "modalLogs": {{ modalLogsQuery.data || [] }},
  "modalTotal": {{
    (modalLogsCountQuery.data && modalLogsCountQuery.data[0])
      ? modalLogsCountQuery.data[0].total
      : 0
  }}
}

comp.sql:
SELECT COUNT(*) AS total
FROM api_fetch_logs
WHERE status = '{{ stateModalStatus.value }}';
